CREATE TABLE "environments" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "environments_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"name" text NOT NULL,
	"description" text DEFAULT '' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "environments_name_unique" UNIQUE("name")
);--> statement-breakpoint
INSERT INTO "environments" ("name", "description") VALUES ('DICE', '');--> statement-breakpoint
ALTER TABLE "projects" ADD COLUMN "environment_id" bigint;--> statement-breakpoint
UPDATE "projects" SET "environment_id" = (SELECT "id" FROM "environments" WHERE "name" = 'DICE');--> statement-breakpoint
ALTER TABLE "projects" ALTER COLUMN "environment_id" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "projects" ADD CONSTRAINT "projects_environment_id_environments_id_fk" FOREIGN KEY ("environment_id") REFERENCES "public"."environments"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "projects_environment_id_idx" ON "projects" USING btree ("environment_id");--> statement-breakpoint
ALTER TABLE "implementation_statements" ADD COLUMN "environment_id" bigint;--> statement-breakpoint
ALTER TABLE "implementation_statements" ALTER COLUMN "project_id" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "implementation_statements" ADD CONSTRAINT "implementation_statements_environment_id_environments_id_fk" FOREIGN KEY ("environment_id") REFERENCES "public"."environments"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
DROP INDEX "implementation_statements_project_outcome_unique";--> statement-breakpoint
