CREATE UNIQUE INDEX "implementation_statements_project_outcome_unique" ON "implementation_statements" USING btree ("project_id","measurable_outcome_id");--> statement-breakpoint
CREATE UNIQUE INDEX "implementation_statements_environment_outcome_unique" ON "implementation_statements" USING btree ("environment_id","measurable_outcome_id");--> statement-breakpoint
CREATE INDEX "implementation_statements_environment_id_idx" ON "implementation_statements" USING btree ("environment_id");--> statement-breakpoint
